-- KRBL Digital Equipment Excel archival import
-- Additive only: does not alter krbl_equipment_transactions or existing Tag Management data.
-- Preserves source rows from all three worksheets exactly as parsed; both balance columns remain separate.
create table if not exists public.krbl_equipment_excel_import (
  id bigint generated always as identity primary key,
  source_file text not null,
  sheet_name text not null check (sheet_name in ('Total','MANDI ISSUE','MANDI RECEIVE')),
  source_row integer not null,
  row_data jsonb not null,
  imported_at timestamptz not null default now(),
  unique(source_file, sheet_name, source_row)
);
alter table public.krbl_equipment_excel_import enable row level security;
drop policy if exists krbl_equipment_excel_admin_read on public.krbl_equipment_excel_import;
create policy krbl_equipment_excel_admin_read on public.krbl_equipment_excel_import for select to authenticated using (exists (select 1 from public.krbl_user_roles r where r.user_id=(select auth.uid()) and r.role='admin'));
drop policy if exists krbl_equipment_excel_admin_insert on public.krbl_equipment_excel_import;
create policy krbl_equipment_excel_admin_insert on public.krbl_equipment_excel_import for insert to authenticated with check (exists (select 1 from public.krbl_user_roles r where r.user_id=(select auth.uid()) and r.role='admin'));

-- Original worksheet rows (header, notes, blank rows excluded; source row numbers retained).

-- Discrepancy summary from the Total worksheet. Values are copied as displayed, not reconciled.
create table if not exists public.krbl_equipment_excel_balance_check (
  item_name text primary key,
  received_from_head_office numeric,
  new_material_in_mandi_ho numeric,
  total_gzbh numeric,
  total_received numeric,
  gzbh_issue numeric,
  total_issue numeric,
  total_issue_calc numeric,
  final_balance_company numeric,
  total_in_company_rs numeric,
  discrepancy numeric generated always as (coalesce(final_balance_company,0)-coalesce(total_in_company_rs,0)) stored,
  imported_at timestamptz not null default now()
);
on conflict (item_name) do update set received_from_head_office=excluded.received_from_head_office,new_material_in_mandi_ho=excluded.new_material_in_mandi_ho,total_gzbh=excluded.total_gzbh,total_received=excluded.total_received,gzbh_issue=excluded.gzbh_issue,total_issue=excluded.total_issue,total_issue_calc=excluded.total_issue_calc,final_balance_company=excluded.final_balance_company,total_in_company_rs=excluded.total_in_company_rs,imported_at=now();
alter table public.krbl_equipment_excel_balance_check enable row level security;
drop policy if exists krbl_equipment_excel_balance_admin_read on public.krbl_equipment_excel_balance_check;
create policy krbl_equipment_excel_balance_admin_read on public.krbl_equipment_excel_balance_check for select to authenticated using (exists (select 1 from public.krbl_user_roles r where r.user_id=(select auth.uid()) and r.role='admin'));